#include <bits/stdc++.h>
using namespace std;

template<typename T = long long>
struct fenwick2d {
    size_t n;
    size_t m;
    vector<vector<T>> bit;

    fenwick2d(size_t rows = 0, size_t cols = 0)
        : n(rows), m(cols), bit(rows + 1, vector<T>(cols + 1, T(0))) {}

    void reset(size_t rows, size_t cols) {
        n = rows; m = cols;
        bit.assign(n + 1, vector<T>(m + 1, T(0)));
    }

    void add(size_t x, size_t y, T delta) {
        assert(x >= 1 && x <= n && y >= 1 && y <= m);
        for (size_t i = x; i <= n; i += i & -i)
            for (size_t j = y; j <= m; j += j & -j)
                bit[i][j] += delta;
    }

    T sum_prefix(size_t x, size_t y) const {
        if (x == 0 || y == 0) return T(0);
        assert(x >= 1 && x <= n && y >= 1 && y <= m);
        T res = T(0);
        for (size_t i = x; i > 0; i -= i & -i)
            for (size_t j = y; j > 0; j -= j & -j)
                res += bit[i][j];
        return res;
    }

    T sum_rect(size_t x1, size_t y1, size_t x2, size_t y2) const {
        assert(1 <= x1 && x1 <= x2 && 1 <= y1 && y1 <= y2);
        assert(x2 <= n && y2 <= m);
        auto pref = [&](size_t x, size_t y) -> T { return sum_prefix(x, y); };
        T res = pref(x2, y2);
        if (x1 > 1) res -= pref(x1 - 1, y2);
        if (y1 > 1) res -= pref(x2, y1 - 1);
        if (x1 > 1 && y1 > 1) res += pref(x1 - 1, y1 - 1);
        return res;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m, q;
    if (!(cin >> n >> m >> q)) return 0;

    fenwick2d<long long> bit(n, m);

    int m_shift = m + n - 1;
    fenwick2d<long long> bit_shifted(n, m_shift);

    vector<vector<int>> mat(n + 1, vector<int>(m + 1, 0));

    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= m; ++j) {
            int val; cin >> val;
            mat[i][j] = val;
            bit.add(i, j, val);
            int j_shift = j + (n - i); 
            bit_shifted.add(i, j_shift, val);
        }
    }

    auto get_stair = [&](int x, int y, int h) -> long long {

        int r1 = x - h + 1;
        int r2 = x;

        int right_shifted = (n - x) + y + h - 1;
        if (right_shifted > m_shift) right_shifted = m_shift; 

        long long pref_diag = bit_shifted.sum_rect(r1, 1, r2, right_shifted);

        long long remain_left = 0;
        if (y > 1) {
            remain_left = bit.sum_rect(r1, 1, r2, y - 1);
        }
        return pref_diag - remain_left;
    };

    while (q--) {
        int t;
        cin >> t;
        if (t == 1) {
            int x, y, v;
            cin >> x >> y >> v;
            long long delta = (long long)v - (long long)mat[x][y];
            if (delta != 0) {
                mat[x][y] = v;
                bit.add(x, y, delta);
                int j_shift = y + (n - x);
                bit_shifted.add(x, j_shift, delta);
            }
        } else if (t == 2) {
            int x, y, h;
            cin >> x >> y >> h;
            cout << get_stair(x, y, h) << '\n';
        } else {
            return 1;
        }
    }
}